import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter/foundation.dart';
import '../data/local_database.dart';
import '../data/paw_repository.dart';
import '../domain/pet.dart';
import '../domain/care_entities.dart';
import '../../features/care/domain/reminder_recurrence.dart';
import '../services/local_notification_service.dart';
import '../services/local_attachment_service.dart';
import '../../features/discover/data/content_update_service.dart';
final databaseProvider=Provider<LocalDatabase>((ref)=>throw UnimplementedError());
final appControllerProvider=ChangeNotifierProvider<AppController>((ref){final c=AppController(PawRepository(ref.watch(databaseProvider)));return c;});
class AppController extends ChangeNotifier {
 AppController(this.repository){refresh();}
 final PawRepository repository;
 final Map<String,List<Map<String,dynamic>>> _data={};
 String? selectedPetId;String weightUnit='lb',distanceUnit='mi',temperatureUnit='°F',locale='en-US';
 bool isLoaded=false;bool onboardingComplete=false,quietHoursEnabled=false;String? migrationWarning;bool _notificationsSynced=false;String quietStart='22:00',quietEnd='07:00';
 List<Pet> get pets=>(_data['pets']??[]).map((e)=>Pet.fromMap(Map<String,Object?>.from(e))).toList();
 Pet? get selectedPet {for(final p in pets){if(p.id==selectedPetId&&!p.archived)return p;}final active=pets.where((p)=>!p.archived).toList();return active.isEmpty?null:active.first;}
 List<Map<String,dynamic>> items(String table)=>List.unmodifiable(_data[table]??const []);
 Future<void> refresh()async{for(final t in PawRepository.tables){_data[t]=await repository.list(t);}selectedPetId=await repository.db.getPreference('selected_pet');final activePets=pets.where((p)=>!p.archived).toList();if(!activePets.any((p)=>p.id==selectedPetId)){selectedPetId=activePets.isEmpty?null:activePets.first.id;if(selectedPetId!=null)await repository.db.setPreference('selected_pet',selectedPetId!);}weightUnit=await repository.db.getPreference('weight_unit')??'lb';distanceUnit=await repository.db.getPreference('distance_unit')??'mi';temperatureUnit=await repository.db.getPreference('temperature_unit')??'°F';quietHoursEnabled=(await repository.db.getPreference('quiet_hours_enabled'))=='1';quietStart=await repository.db.getPreference('quiet_hours_start')??'22:00';quietEnd=await repository.db.getPreference('quiet_hours_end')??'07:00';migrationWarning=await repository.db.getPreference('legacy_migration_error');onboardingComplete=(await repository.db.getPreference('onboarding_complete'))=='1';if(!_notificationsSynced){_notificationsSynced=true;try{if(await LocalNotificationService.instance.notificationsEnabled()){for(final raw in _data['reminders']??const []){final reminder=Reminder.fromMap(raw);if(reminder.enabled&&!reminder.completed)await _scheduleReminder(reminder);}}}catch(_){}}isLoaded=true;notifyListeners();}
 Future<void> _scheduleReminder(Reminder reminder)async{await LocalNotificationService.instance.schedule(reminder,quietHoursEnabled:quietHoursEnabled,quietStart:quietStart,quietEnd:quietEnd);}
 Future<void> saveQuietHours({required bool enabled,required String start,required String end})async{quietHoursEnabled=enabled;quietStart=start;quietEnd=end;await repository.db.setPreference('quiet_hours_enabled',enabled?'1':'0');await repository.db.setPreference('quiet_hours_start',start);await repository.db.setPreference('quiet_hours_end',end);await resyncNotifications();notifyListeners();}
 Future<void> resyncNotifications()async{try{await LocalNotificationService.instance.refreshTimezone();await LocalNotificationService.instance.cancelAll();if(await LocalNotificationService.instance.notificationsEnabled()){for(final raw in _data['reminders']??const []){final r=Reminder.fromMap(raw);if(r.enabled&&!r.completed)await _scheduleReminder(r);}}}catch(_){}}
 Future<void> save(String table,Map<String,Object?> value)async{await repository.save(table,value);await refresh();}
 Future<void> delete(String table,String id)async{await repository.delete(table,id);await refresh();}
 Future<void> permanentlyDeletePet(String id)async{final pet=pets.where((p)=>p.id==id).first;final paths=<String>[if(pet.photoPath.isNotEmpty)pet.photoPath,...(_data['pet_records']??const []).where((e)=>e['petId']==id&&e['attachmentPath'] is String).map((e)=>e['attachmentPath'] as String),...(_data['care_logs']??const []).where((e)=>e['petId']==id&&e['attachmentPath'] is String).map((e)=>e['attachmentPath'] as String)];for(final raw in _data['reminders']??const []){if(raw['petId']==id){try{await LocalNotificationService.instance.cancel(raw['id'] as String);}catch(_){}}}await repository.deletePet(id);for(final path in paths){try{await LocalAttachmentService().delete(path);}catch(_){}}if(selectedPetId==id)selectedPetId=null;await repository.db.setPreference('selected_pet',selectedPetId??'');await refresh();}
 Future<void> saveReminder(Reminder reminder)async{await LocalNotificationService.instance.cancel(reminder.id);await repository.save('reminders',reminder.toMap());await refresh();if(reminder.enabled&&!reminder.completed&&await LocalNotificationService.instance.notificationsEnabled())await _scheduleReminder(reminder);}
 Future<void> updateReminder(Reminder reminder,{bool? enabled})async{final next=Reminder(id:reminder.id,petId:reminder.petId,title:reminder.title,category:reminder.category,dueAt:reminder.dueAt,repeat:reminder.repeat,weekdays:reminder.weekdays,intervalDays:reminder.intervalDays,monthEndPolicy:reminder.monthEndPolicy,note:reminder.note,enabled:enabled??reminder.enabled,completed:reminder.completed,snoozedUntil:reminder.snoozedUntil);await saveReminder(next);}
 Future<void> reopenReminder(Reminder reminder)async{final next=Reminder(id:reminder.id,petId:reminder.petId,title:reminder.title,category:reminder.category,dueAt:reminder.dueAt,repeat:reminder.repeat,weekdays:reminder.weekdays,intervalDays:reminder.intervalDays,monthEndPolicy:reminder.monthEndPolicy,note:reminder.note,enabled:reminder.enabled,completed:false,snoozedUntil:reminder.snoozedUntil);await saveReminder(next);}
 Future<void> deleteReminder(Reminder reminder)async{await LocalNotificationService.instance.cancel(reminder.id);await repository.delete('reminders',reminder.id);await refresh();}
 DateTime? _nextFutureOccurrence(Reminder reminder){var next=ReminderRecurrence.next(reminder.dueAt,reminder.repeat,intervalDays:reminder.intervalDays,weekdays:reminder.weekdays,monthEndPolicy:reminder.monthEndPolicy);var guard=0;while(next!=null&&!next.isAfter(DateTime.now())&&guard<400){next=ReminderRecurrence.next(next,reminder.repeat,intervalDays:reminder.intervalDays,weekdays:reminder.weekdays,monthEndPolicy:reminder.monthEndPolicy);guard++;}return next;}
 Future<void> skipReminder(Reminder reminder)async{final next=_nextFutureOccurrence(reminder);await LocalNotificationService.instance.cancel(reminder.id);if(next==null){await repository.save('reminders',{...reminder.toMap(),'completed':1});}else{await repository.save('reminders',{...reminder.toMap(),'dueAt':next.toIso8601String(),'completed':0,'snoozedUntil':null});}final log=CareLog(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:reminder.petId,type:'Reminder skipped',title:reminder.title,at:DateTime.now(),note:'Skipped from PawPal schedule.');await repository.save('care_logs',log.toMap());await refresh();if(next!=null&&reminder.enabled)await _scheduleReminder(Reminder(id:reminder.id,petId:reminder.petId,title:reminder.title,category:reminder.category,dueAt:next,repeat:reminder.repeat,weekdays:reminder.weekdays,intervalDays:reminder.intervalDays,monthEndPolicy:reminder.monthEndPolicy,note:reminder.note));}
 Future<void> completeReminder(Reminder reminder)async{final next=_nextFutureOccurrence(reminder);await LocalNotificationService.instance.cancel(reminder.id);if(next==null){await repository.save('reminders',{...reminder.toMap(),'completed':1});}else{await repository.save('reminders',{...reminder.toMap(),'dueAt':next.toIso8601String(),'completed':0,'snoozedUntil':null});}final log=CareLog(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:reminder.petId,type:'Reminder completed',title:reminder.title,at:DateTime.now(),note:'Completed from PawPal schedule.');await repository.save('care_logs',log.toMap());await refresh();if(next!=null&&reminder.enabled){await _scheduleReminder(Reminder(id:reminder.id,petId:reminder.petId,title:reminder.title,category:reminder.category,dueAt:next,repeat:reminder.repeat,weekdays:reminder.weekdays,intervalDays:reminder.intervalDays,monthEndPolicy:reminder.monthEndPolicy,note:reminder.note));}}
 Future<void> snoozeReminder(Reminder reminder,Duration duration)async{final until=DateTime.now().add(duration);final data={...reminder.toMap(),'snoozedUntil':until.toIso8601String()};await repository.save('reminders',data);await refresh();if(reminder.enabled)await _scheduleReminder(Reminder(id:reminder.id,petId:reminder.petId,title:reminder.title,category:reminder.category,dueAt:until,repeat:'once',note:reminder.note));}
 Future<void> selectPet(String? id)async{selectedPetId=id;if(id==null){notifyListeners();return;}await repository.db.setPreference('selected_pet',id);notifyListeners();}
 Future<void> saveUnits({String? weight,String? distance,String? temperature})async{if(weight!=null)weightUnit=weight;if(distance!=null)distanceUnit=distance;if(temperature!=null)temperatureUnit=temperature;await repository.db.setPreference('weight_unit',weightUnit);await repository.db.setPreference('distance_unit',distanceUnit);await repository.db.setPreference('temperature_unit',temperatureUnit);notifyListeners();}
 Future<void> completeOnboarding()async{onboardingComplete=true;await repository.db.setPreference('onboarding_complete','1');notifyListeners();}
 Future<void> clearReadingHistory()async{await repository.db.clearTable('reading_history');await refresh();}
 Future<void> clearAllLocalData()async{await LocalNotificationService.instance.cancelAll();await repository.db.clearAll();await repository.db.setPreference('legacy_preferences_migrated','1');await LocalAttachmentService().clearAll();await ContentUpdateService().clearCache();selectedPetId=null;_data.clear();migrationWarning=null;isLoaded=true;onboardingComplete=false;notifyListeners();}
 Future<String> exportData()=>repository.exportAll();
 Future<Map<String,List<Map<String,dynamic>>>> validateBackup(String source)=>repository.validateImport(source);
 Future<void> restoreBackup(Map<String,List<Map<String,dynamic>>> data,{required bool replaceExisting})async{await LocalNotificationService.instance.cancelAll();await repository.restore(data,replaceExisting:replaceExisting);await refresh();await resyncNotifications();}
}
